<body>
    <div class="container">
        <header>
            <h1>Computer Languages Quiz</h1>
            <p class="subtitle">Test your knowledge of programming paradigms and ecosystems.</p>
        </header>

        <main id="root">
            <!-- App will be rendered here -->
        </main>
    </div>

    <script>
        // Quiz Data
        const QUIZ_DATA = [
            {
                id: 'q1',
                question: 'Which of these languages are statically typed?',
                helpText: 'Statically typed languages perform type checking at compile-time rather than at run-time.',
                options: ['C++', 'Python', 'Java', 'JavaScript'],
                correct: [0, 2]
            },
            {
                id: 'q2',
                question: 'Which of these are considered low-level or "close to the metal" languages?',
                options: ['C', 'Rust', 'Ruby', 'PHP'],
                correct: [0, 1]
            },
            {
                id: 'q3',
                question: 'Which of these are popular for data science and machine learning?',
                options: ['Python', 'R', 'CSS', 'HTML'],
                correct: [0, 1]
            }
        ];

        // State Management
        let state = {
            selections: {
                q1: [],
                q2: [],
                q3: []
            },
            submitted: false,
            score: 0
        };

        // Actions
        function toggleSelection(questionId, optionIndex) {
            const current = state.selections[questionId];
            if (current.includes(optionIndex)) {
                state.selections[questionId] = current.filter(i => i !== optionIndex);
            } else {
                state.selections[questionId] = [...current, optionIndex];
            }
            render();
        }

        function handleSubmit(e) {
            e.preventDefault();

            let totalScore = 0;
            QUIZ_DATA.forEach(q => {
                const selected = state.selections[q.id].sort();
                const correct = q.correct.sort();
                if (JSON.stringify(selected) === JSON.stringify(correct)) {
                    totalScore++;
                }
            });

            state.score = totalScore;
            state.submitted = true;
            render();

            // Move focus to result message for screen readers
            setTimeout(() => {
                document.getElementById('result-heading')?.focus();
            }, 100);
        }

        function handleReset() {
            state = {
                selections: { q1: [], q2: [], q3: [] },
                submitted: false,
                score: 0
            };
            render();
        }

        // Components (React-style)
        function Option({ questionId, option, index, isChecked }) {
            const id = `${questionId}-opt-${index}`;

            const div = document.createElement('div');
            div.className = 'option-item';
            div.onclick = () => toggleSelection(questionId, index);

            const input = document.createElement('input');
            input.type = 'checkbox';
            input.id = id;
            input.checked = isChecked;
            input.onchange = (e) => {
                e.stopPropagation();
                toggleSelection(questionId, index);
            };

            const label = document.createElement('label');
            label.setAttribute('for', id);
            label.textContent = option;
            label.onclick = (e) => e.stopPropagation();

            div.appendChild(input);
            div.appendChild(label);
            return div;
        }

        function Question({ qData }) {
            const div = document.createElement('div');
            div.className = 'form-field';

            const fieldset = document.createElement('fieldset');
            const helpId = `${qData.id}-help`;

            if (qData.helpText) {
                fieldset.setAttribute('aria-describedby', helpId);
            }

            const legend = document.createElement('legend');
            legend.textContent = qData.question;
            fieldset.appendChild(legend);

            if (qData.helpText) {
                const p = document.createElement('p');
                p.id = helpId;
                p.className = 'help-text';
                p.textContent = qData.helpText;
                fieldset.appendChild(p);
            }

            const optionsList = document.createElement('div');
            optionsList.className = 'options-list';

            qData.options.forEach((opt, idx) => {
                const isChecked = state.selections[qData.id].includes(idx);
                optionsList.appendChild(Option({ 
                    questionId: qData.id, 
                    option: opt, 
                    index: idx, 
                    isChecked 
                }));
            });

            fieldset.appendChild(optionsList);
            div.appendChild(fieldset);
            return div;
        }

        function Quiz() {
            if (state.submitted) {
                const div = document.createElement('div');
                div.className = 'quiz-card results';
                div.setAttribute('aria-live', 'polite');

                const h2 = document.createElement('h2');
                h2.id = 'result-heading';
                h2.tabIndex = -1; // Allow focus
                h2.textContent = `Quiz Complete!`;

                const p = document.createElement('p');
                p.textContent = `You scored ${state.score} out of ${QUIZ_DATA.length}.`;

                const btn = document.createElement('button');
                btn.className = 'reset-btn';
                btn.textContent = 'Try Again';
                btn.onclick = handleReset;

                div.appendChild(h2);
                div.appendChild(p);
                div.appendChild(btn);
                return div;
            }

            const form = document.createElement('form');
            form.className = 'quiz-card';
            form.onsubmit = handleSubmit;

            QUIZ_DATA.forEach(q => {
                form.appendChild(Question({ qData: q }));
            });

            const submitBtn = document.createElement('button');
            submitBtn.type = 'submit';
            submitBtn.className = 'submit-btn';
            submitBtn.textContent = 'Submit Answers';
            form.appendChild(submitBtn);

            return form;
        }

        // Render Engine
        function render() {
            const root = document.getElementById('root');
            root.innerHTML = '';
            root.appendChild(Quiz());
        }

        // Initial Render
        render();
    </script>
</body>
</html>
