const fs = require('fs');
const path = require('path');

async function runA11yTest() {
    let browser;
    try {
        browser = await chromium.launch();
        const context = await browser.newContext();
        const page = await context.newPage();

        const htmlPath = path.resolve('index.html');
        const content = fs.readFileSync(htmlPath, 'utf8');
        await page.setContent(content, { waitUntil: 'load' });

        // Test initial state
        const axeSource = require('axe-core').source;
        await page.evaluate(axeSource);
        const resultsInitial = await page.evaluate(async () => await window.axe.run());

        // Simulate submission
        await page.click('.submit-btn');
        const resultsSubmitted = await page.evaluate(async () => await window.axe.run());

        const allViolations = [...resultsInitial.violations, ...resultsSubmitted.violations];
        // Unique violations
        const uniqueViolations = [];
        const seen = new Set();
        for (const v of allViolations) {
            const key = `${v.id}-${JSON.stringify(v.nodes.map(n => n.target))}`;
            if (!seen.has(key)) {
                uniqueViolations.push(v);
                seen.add(key);
            }
        }

        const wcag = uniqueViolations.filter(v => !v.tags.includes('best-practice'));
        const bp = uniqueViolations.filter(v => v.tags.includes('best-practice'));

        console.log(JSON.stringify({
            wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
            bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
        }, null, 2));

        process.exit(wcag.length > 0 ? 1 : 0);
    } catch (error) {
        console.error('Error running a11y test:', error);
        process.exit(1);
    } finally {
        if (browser) await browser.close();
    }
}

